/** Light or dark appearance. */
enum class MistyAppearance { Light, Dark }

/** An OKLCH colour. When [followsHue] is true, [h] is an offset from the Misty hue. */
data class MistyOklch(val l: Double, val c: Double, val h: Double, val alpha: Double, val followsHue: Boolean) {
    /** sRGB, clipped per channel as browsers do on sRGB displays. */
    fun toColor(hue: Double): Color {
        val angle = (if (followsHue) hue + h else h) * PI / 180.0
        val a = c * cos(angle)
        val b = c * sin(angle)
        val l3 = (l + 0.3963377774 * a + 0.2158037573 * b).pow(3)
        val m3 = (l - 0.1055613458 * a - 0.0638541728 * b).pow(3)
        val s3 = (l - 0.0894841775 * a - 1.2914855480 * b).pow(3)
        fun encode(v: Double): Float {
            val g = if (v <= 0.0031308) 12.92 * v else 1.055 * v.pow(1.0 / 2.4) - 0.055
            return g.coerceIn(0.0, 1.0).toFloat()
        }
        return Color(
            red = encode(4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3),
            green = encode(-1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3),
            blue = encode(-0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3),
            alpha = alpha.toFloat(),
        )
    }
}

/** A colour token with a light and a dark value. */
data class MistyThemedColor(val light: MistyOklch, val dark: MistyOklch) {
    fun resolve(hue: Double, appearance: MistyAppearance): Color =
        (if (appearance == MistyAppearance.Dark) dark else light).toColor(hue)
}

