/** Glass: a tint of the field at a grade's alpha. Compose can't blur what lies behind a
 * surface, so draw glass as the cloud colour unless the platform blurs behind it (PLT-05). */
object MistyGlass {
    const val Lightness = 0.995
    const val LightnessDark = 0.215
    const val Chroma = 0.004
    const val ChromaDark = 0.02
    const val Saturation = 1.75

    fun alpha(grade: MistyGlassGrade, appearance: MistyAppearance): Double {
        val dark = appearance == MistyAppearance.Dark
        return when (grade) {
            MistyGlassGrade.Clear -> if (dark) 0.36 else 0.3
            MistyGlassGrade.Mist -> if (dark) 0.5 else 0.42
            MistyGlassGrade.Veil -> if (dark) 0.68 else 0.62
        }
    }

    /** The blur's standard deviation in dp, as in CSS. */
    fun blur(grade: MistyGlassGrade): Dp = when (grade) {
        MistyGlassGrade.Clear -> 24.dp
        MistyGlassGrade.Mist -> 26.dp
        MistyGlassGrade.Veil -> 32.dp
    }
}

/** Resolves Misty's colours for one hue and appearance. */
class MistyTheme(val hue: Double = 250.0, val appearance: MistyAppearance = MistyAppearance.Light) {
    fun color(token: MistyThemedColor): Color = token.resolve(hue, appearance)

    /** The fill of a glass grade, before blur. */
    fun glassFill(grade: MistyGlassGrade): Color {
        val dark = appearance == MistyAppearance.Dark
        return MistyOklch(
            if (dark) MistyGlass.LightnessDark else MistyGlass.Lightness,
            if (dark) MistyGlass.ChromaDark else MistyGlass.Chroma,
            0.0, MistyGlass.alpha(grade, appearance), true,
        ).toColor(hue)
    }

    val sky: Color get() = color(MistyColorTokens.Sky)
    val skyHigh: Color get() = color(MistyColorTokens.SkyHigh)
