}

/** Fluid type sizes from the window's width in dp. Sizes are in sp, so they follow
 * the person's font scale (PLT-06). */
object MistyType {
    fun display(windowWidthDp: Float): TextUnit = (windowWidthDp * 0.066f).coerceIn(52.0f, 92.0f).sp
    fun h1(windowWidthDp: Float): TextUnit = (windowWidthDp * 0.046f).coerceIn(38.4f, 60.0f).sp
    fun h2(windowWidthDp: Float): TextUnit = (windowWidthDp * 0.034f).coerceIn(30.4f, 44.0f).sp
    fun h3(windowWidthDp: Float): TextUnit = (windowWidthDp * 0.02f).coerceIn(20.8f, 24.0f).sp
    fun lede(windowWidthDp: Float): TextUnit = (windowWidthDp * 0.015f).coerceIn(17.0f, 19.0f).sp
    /** The longest line of running text, in characters. */
    const val Measure = 68
}

/** Page widths and fluid spacing in dp. */
object MistyLayout {
    val Page: Dp = 1200.dp
    val PageDocs: Dp = 1312.dp
    val Reading: Dp = 704.dp
    val NavHeight: Dp = 72.dp
    fun gutter(windowWidthDp: Float): Dp = (windowWidthDp * 0.04f).coerceIn(18.0f, 32.0f).dp
    fun section(windowWidthDp: Float): Dp = (windowWidthDp * 0.09f).coerceIn(64.0f, 120.0f).dp
}

/** The five window classes, measured on the window's width. */
enum class MistyWindowClass {
    Narrow, Compact, Medium, Expanded, Wide;

    companion object {
        fun from(widthDp: Float): MistyWindowClass = when {
            widthDp <= 380f -> Narrow
            widthDp <= 767f -> Compact
            widthDp <= 1023f -> Medium
            widthDp <= 1179f -> Expanded
            else -> Wide
        }
    }
}

